// Exam and bank tools: item IDs remain stable and choice shuffle is stored per session.
function exam(){if(state.activeExam){session=state.activeExam;session.flags=session.flags||[];pos=Math.min(session.pos||0,session.ids.length-1);drawQuestion();return}if(result){showExamResult(result);return}$('#app').innerHTML=heading('模拟考试，练题也练节奏。','训练卷按题目等权折算百分制，多选全对才计分。200题配置只参考公开实例，不是官方原卷。')+`<div class="cards"><section class="card"><span class="pill">轻量检测</span><h2>20 题 / 20 分钟</h2><p class="muted">六模块覆盖，快速检查今天学得怎么样。</p><button class="primary" onclick="startExam(20,20)">开始快速检测</button></section><section class="card"><span class="pill">综合训练</span><h2>60 题 / 90 分钟</h2><p class="muted">适合完成一轮学习后整体复盘。</p><button class="primary" onclick="startExam(60,90)">开始综合模拟</button></section><section class="card"><span class="pill">节奏训练</span><h2>200 题 / 90 分钟</h2><p class="muted">题目来自本站题库；题型和模块比例为本站组卷设计。</p><button class="primary" onclick="startExam(200,90)">开始 200 题训练</button></section><section class="card"><span class="pill">自主设置</span><h2>自定义组卷</h2><div class="toolbar"><label>题数 <input id="examN" type="number" min="5" max="${questions.length}" value="50" style="width:80px"></label><label>分钟 <input id="examMinutes" type="number" min="1" max="240" value="45" style="width:80px"></label></div><label>模块 <select id="examModule">${selectOptions([['all','全部模块'],...modules.map((m,i)=>[i,m[0]])],'all')}</select></label><div class="toolbar"><label>单选 <input id="ratioSingle" type="number" min="0" value="60" style="width:70px">%</label><label>多选 <input id="ratioMulti" type="number" min="0" value="20" style="width:70px">%</label><label>判断 <input id="ratioJudge" type="number" min="0" value="20" style="width:70px">%</label></div><p class="muted">比例合计须为100%；某题型不足时会明确提示，不静默替换。</p><button onclick="customExam()">生成试卷</button></section></div><section class="card" style="margin-top:24px"><h2>考试记录</h2>${state.exams.length?`<div class="table-scroll"><table><thead><tr><th>交卷时间</th><th>题量</th><th>分数</th><th>操作</th></tr></thead><tbody>${state.exams.slice().reverse().map(e=>`<tr><td>${new Date(e.at).toLocaleString('zh-CN')}</td><td>${e.ids.length}</td><td>${e.score}</td><td><button onclick="showExamResult(state.exams.find(x=>x.at===${e.at}))">查看解析</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">暂无考试记录。第一次成绩是起点。</p>'}</section><p class="note" style="margin-top:22px">练习卷包含原创概念、情境和计算变式；默认均匀覆盖六模块，题型由抽中的题目自然形成。自定义卷可指定题型比例。技能操作请同时进入交互实操与实操案例。</p>`}
function makeExamIds(n,m='all',ratios=null){let qs=questions.filter(q=>m==='all'||q.m==m);if(n>qs.length)throw Error(`当前范围仅有 ${qs.length} 题，请减少题量。`);if(ratios){let counts=[Math.floor(n*ratios[0]/100),Math.floor(n*ratios[1]/100)];counts.push(n-counts[0]-counts[1]);let ids=[];['单选','多选','判断'].forEach((type,i)=>{let pool=qs.filter(q=>q.type===type);if(pool.length<counts[i])throw Error(`${type}需要${counts[i]}题，当前范围只有${pool.length}题，请调整题量或比例。`);ids.push(...shuffled(pool).slice(0,counts[i]).map(q=>q.id))});return shuffled(ids)}let groups=modules.map((_,i)=>shuffled(qs.filter(q=>q.m===i)));let ids=[];while(ids.length<n){let advanced=false;for(let g of groups)if(g.length&&ids.length<n){ids.push(g.pop().id);advanced=true}if(!advanced)break}return shuffled(ids)}
function customExam(){let n=Number($('#examN').value),min=Number($('#examMinutes').value),ratios=[$('#ratioSingle'),$('#ratioMulti'),$('#ratioJudge')].map(el=>Number(el.value));if(!ratios.every(x=>Number.isFinite(x)&&x>=0&&x<=100)||Math.abs(ratios.reduce((a,b)=>a+b,0)-100)>.0001){toast('三种题型比例必须是0–100的数值，且合计100%');return}startExam(n,min,$('#examModule').value,ratios)}
function startExam(n,min,m='all',ratios=null){if(!Number.isInteger(n)||n<5||!Number.isFinite(min)||min<1||min>240){toast('题数须为至少5的整数，时长须为1–240分钟');return}if(state.activeExam){toast('已有进行中的考试');go('exam');return}let ids;try{ids=makeExamIds(n,m,ratios)}catch(e){toast(e.message);return}let orders={};ids.forEach(id=>{let q=qby(id);orders[id]=q.type==='判断'?q.options.map((_,i)=>i):shuffled(q.options.map((_,i)=>i))});session={exam:true,ids,orders,flags:[],answers:{},end:Date.now()+min*60000,started:Date.now(),pos:0,config:{n,min,m,ratios}};state.activeExam=session;pos=0;selection=[];result=null;save();go('exam')}
function toggleFlag(id){session.flags=session.flags||[];session.flags=session.flags.includes(id)?session.flags.filter(x=>x!==id):[...session.flags,id];persistSession();drawQuestion()}
function tick(){let active=state.activeExam;if(!active)return;let secs=Math.max(0,Math.ceil((active.end-Date.now())/1000));if($('#timer'))$('#timer').textContent=`剩余 ${Math.floor(secs/60)}:${String(secs%60).padStart(2,'0')}`;if(!secs)finishExam(true)}
function finishExam(auto){let s=state.activeExam;if(!s||s.finishing)return;let unanswered=s.ids.filter(id=>!s.answers[id]?.length).length;if(!auto&&!confirm(`确认交卷？${unanswered?`还有${unanswered}题未答，按错误计分。`:'交卷后不能修改答案。'}`))return;s.finishing=true;let right=0;s.ids.forEach(id=>{if(recordAnswer(qby(id),s.answers[id]||[],'exam'))right++});result={...s,at:Date.now(),score:Math.round(right/s.ids.length*10000)/100,right,auto};delete result.finishing;state.exams.push(result);state.activeExam=null;session=null;save();if(page==='exam')showExamResult(result);else toast('模拟考试已到时交卷，可到考试中心查看成绩')}
function showExamResult(e){result=e;reportFilter='all';drawExamReport()}
function drawExamReport(){let e=result;if(!e)return;let ids=e.ids.filter(id=>reportFilter==='all'||!eq(e.answers[id]||[],qby(id).answer));$('#app').innerHTML=heading('考试复盘，找到下一步。','正确率只是结果。分模块定位问题，再回到相应要点与实操。')+`<section class="card"><div class="row"><div><div class="score">${e.score}<small style="font-size:18px"> / 100</small></div><p>答对 ${e.right}/${e.ids.length} · ${e.auto?'到时自动交卷':'手动交卷'} · 用时 ${Math.max(1,Math.ceil((Math.min(e.at,e.end)-e.started)/60000))} 分钟</p></div><button onclick="result=null;exam()">返回考试中心</button></div><div class="stats">${modules.map((m,i)=>{let group=e.ids.filter(id=>qby(id).m===i),r=group.filter(id=>eq(e.answers[id]||[],qby(id).answer)).length;return `<div><small>${m[0]}</small><h3>${r}/${group.length}</h3><div class="progress"><div style="width:${pct(r,group.length)}%"></div></div></div>`}).join('')}</div><div class="actions"><button onclick="startList(result.ids.filter(id=>!eq(result.answers[id]||[],qby(id).answer)),'本次考试错题')">重练本次错题</button><button onclick="exportExam()">导出考试报告</button><button onclick="reportFilter=reportFilter==='all'?'wrong':'all';drawExamReport()">${reportFilter==='all'?'只看错题':'显示全部题目'}</button></div></section><section class="card" style="margin-top:22px"><h2>逐题解析 · ${ids.length} 题</h2>${ids.map(id=>{let q=qby(id),ans=e.answers[id]||[],order=e.orders?.[id]||q.options.map((_,i)=>i),letters=a=>order.map((j,i)=>a.includes(j)?'ABCDEF'[i]:'').filter(Boolean).join('、');return `<details><summary>${eq(ans,q.answer)?'✓':'○'} ${e.ids.indexOf(id)+1}. ${esc(q.stem)}</summary><p>${order.map((j,i)=>`${'ABCDEF'[i]}．${esc(q.options[j])}`).join('<br>')}</p><p>你的答案：${letters(ans)||'未作答'}　正确答案：${letters(q.answer)}</p><p class="note">${esc(q.explain)}</p></details>`}).join('')}</section>`}
function exportExam(){if(!result)return;let e=result;downloadFile('考试复盘-'+new Date(e.at).toISOString().slice(0,10)+'.md',`# 模拟考试复盘\n\n成绩：${e.score}/100；答对${e.right}/${e.ids.length}\n\n`+e.ids.map((id,i)=>{let q=qby(id),a=e.answers[id]||[];return `## ${i+1}. ${q.stem}\n\n我的选择：${a.map(j=>q.options[j]).join('；')||'未答'}\n\n正确答案：${q.answer.map(j=>q.options[j]).join('；')}\n\n解析：${q.explain}\n`}).join('\n'),'text/markdown;charset=utf-8')}
function bank(){ $('#app').innerHTML=heading('题库管理，查找与扩展。','内置原创题与计算变式分开标注。可导入自己的合法题目，导入前会校验并显示预览。')+filterBar()+`<section class="card"><div class="row"><p class="muted">内置 ${builtInCount} · 自导入 ${state.custom.length} · 当前范围 <b id="qcount">${pool().length}</b></p><button onclick="startFiltered()">练习当前范围</button></div><div id="bankRows"></div></section><section class="card" style="margin-top:22px"><h2>扩展自己的题库</h2><p class="muted">支持JSON数组，单次最多1000题、5MB。模块编号0–5；答案使用从0开始的选项索引。导入不会修改内置题。</p><div class="actions"><button onclick="downloadTemplate()">下载导入模板</button><label class="file-button">选择题库 JSON<input type="file" accept=".json,application/json" onchange="previewBankImport(event)"></label><button onclick="downloadFile('我的题库.json',JSON.stringify(state.custom,null,2))">导出自有题库</button><button onclick="downloadFile('当前筛选题库.json',JSON.stringify(pool(),null,2))">导出当前范围</button></div><div id="bankPreview"></div></section>`;drawBankRows()}
function drawBankRows(){let qs=pool(),pages=Math.max(1,Math.ceil(qs.length/15));bankPage=Math.max(0,Math.min(bankPage,pages-1));$('#qcount').textContent=qs.length;$('#bankRows').innerHTML=qs.slice(bankPage*15,bankPage*15+15).map(q=>`<details><summary><span class="pill">${esc(q.type)} · ${esc(q.difficulty)}</span> ${esc(q.stem)}</summary><p class="muted">${esc(q.id)} · ${modules[q.m][0]} · ${esc(q.source)}</p><p>${q.options.map((o,i)=>`${'ABCDEF'[i]}．${esc(o)}`).join('<br>')}</p><p>答案：${q.answer.map(i=>'ABCDEF'[i]).join('、')}</p><p class="note">${esc(q.explain)}</p><button onclick="startList(['${q.id}'],'题库单题练习')">练习此题</button></details>`).join('')||'<p class="empty">没有匹配题目，请调整筛选条件。</p>';$('#bankRows').insertAdjacentHTML('beforeend',`<div class="row" style="margin-top:20px"><button onclick="bankPage--;drawBankRows()" ${bankPage===0?'disabled':''}>上一页</button><span>${bankPage+1}/${pages} 页</span><button onclick="bankPage++;drawBankRows()" ${bankPage===pages-1?'disabled':''}>下一页</button></div>`)}
function downloadTemplate(){downloadFile('题库导入模板.json',JSON.stringify([{id:'my-question-001',m:3,type:'单选',stem:'训练集表现很好，但验证集明显较差，首先应采取哪种做法？',options:['检查过拟合与数据分布差异','删除验证集','直接宣布模型合格','把验证答案加入输入'],answer:[0],explain:'先排查过拟合、分布差异与划分问题，再选择正则化、补数据等措施。',tag:'过拟合',difficulty:'基础',source:'个人原创'}],null,2))}
async function previewBankImport(ev){let file=ev.target.files[0];ev.target.value='';if(!file)return;try{if(file.size>5e6)throw Error('文件超过5MB');let rows=JSON.parse(await file.text());if(!Array.isArray(rows)||!rows.length||rows.length>1000)throw Error('须为1–1000题的JSON数组');let seen=new Set(questions.map(q=>q.stem.trim())),accepted=[],duplicates=0;for(let [i,row]of rows.entries()){let q={...row,id:`custom-${Date.now().toString(36)}-${i}`,difficulty:['基础','进阶','应用'].includes(row.difficulty)?row.difficulty:'基础',source:'自导入',tag:typeof row.tag==='string'?row.tag.slice(0,60):'自有题目'};if(!validQuestion(q))throw Error(`第${i+1}题字段不合法，请检查题型、选项、答案索引和解析`);if(seen.has(q.stem.trim())){duplicates++;continue}seen.add(q.stem.trim());accepted.push(q)}draftBank=accepted;$('#bankPreview').innerHTML=`<div class="note" style="margin-top:20px"><b>校验通过</b><p>可导入 ${accepted.length} 题；跳过 ${duplicates} 道同题干重复题。</p>${accepted.slice(0,3).map(q=>`<p>${esc(q.stem)}</p>`).join('')}<button class="primary" onclick="commitBankImport()" ${!accepted.length?'disabled':''}>确认导入 ${accepted.length} 题</button> <button onclick="draftBank=null;document.getElementById('bankPreview').innerHTML=''">取消</button></div>`}catch(e){draftBank=null;toast('导入失败：'+e.message)}}
function commitBankImport(){if(!draftBank?.length)return;questions.push(...draftBank);state.custom.push(...draftBank);let n=draftBank.length;draftBank=null;save();bank();toast(`成功导入${n}题`)}
function moduleStats(){let latest=latestMap();return modules.map((m,i)=>{let qs=questions.filter(q=>q.m===i),attempted=qs.filter(q=>latest[q.id]),right=attempted.filter(q=>latest[q.id].ok).length;return{m:i,total:qs.length,done:attempted.length,right,accuracy:pct(right,attempted.length)}})}
function analytics(){let stats=moduleStats(),recent=state.history.slice(-100),days=Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);let key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;let n=state.history.filter(h=>{let x=new Date(h.at);return x.getFullYear()===d.getFullYear()&&x.getMonth()===d.getMonth()&&x.getDate()===d.getDate()}).length;return{key,n}}),max=Math.max(1,...days.map(d=>d.n));$('#app').innerHTML=heading('学习分析，看见真实薄弱点。','模块正确率按每题最近一次作答统计；未作答题目不算错误，覆盖率单独展示。')+`<div class="stats"><div class="card stat"><small>已覆盖题目</small><strong>${Object.keys(latestMap()).length}</strong><small>共 ${questions.length} 题</small></div><div class="card stat"><small>最近100次正确率</small><strong>${pct(recent.filter(x=>x.ok).length,recent.length)}%</strong><small>实际统计 ${recent.length} 次</small></div><div class="card stat"><small>完成模考</small><strong>${state.exams.length}</strong><small>最高 ${state.exams.length?Math.max(...state.exams.map(e=>e.score)):0} 分</small></div><div class="card stat"><small>交互实操记录</small><strong>${Object.keys(state.labs).length}</strong><small>共5个任务，取最近成绩</small></div></div><section class="card"><h2>模块掌握情况</h2>${stats.map(s=>`<div class="module"><div class="row"><div><h3>${modules[s.m][0]}</h3><span class="muted">覆盖 ${s.done}/${s.total} · 最近答对 ${s.right}/${s.done} · ${s.done?s.accuracy+'%':'暂无数据'}</span></div><button onclick="startPractice('${s.m}',20)">专项补强</button></div><div class="progress"><div style="width:${s.accuracy}%"></div></div></div>`).join('')}</section><div class="cards" style="margin-top:22px"><section class="card"><h2>最近7天练习量</h2><div class="bar-chart">${days.map(d=>`<div><strong>${d.n}</strong><div class="bar" style="height:${Math.max(3,d.n/max*130)}px"></div><small>${d.key.slice(5)}</small></div>`).join('')}</div></section><section class="card"><h2>错因分布</h2>${['概念不清','审题失误','公式混淆','操作不熟','遗漏条件'].map(c=>`<div class="row"><span>${c}</span><b>${Object.values(state.causes).filter(x=>x===c).length}</b></div>`).join('')}<p class="muted">来自你手动标注的错因，不是自动推断。</p><label>每日训练目标 <select aria-label="每日训练目标" onchange="state.settings.daily=Number(this.value);save()">${selectOptions([[10,'10题'],[20,'20题'],[30,'30题'],[50,'50题']],state.settings.daily)}</select></label></section></div><section class="card" style="margin-top:22px"><h2>最近10次模考趋势</h2>${state.exams.length?`<div class="bar-chart">${state.exams.slice(-10).map((e,i)=>`<div><strong>${e.score}</strong><div class="bar" style="height:${Math.max(3,e.score*1.3)}px"></div><small>第${Math.max(0,state.exams.length-10)+i+1}次</small></div>`).join('')}</div>`:'<p class="muted">完成模拟考试后显示成绩趋势。</p>'}<button onclick="downloadFile('学习分析-'+today()+'.json',JSON.stringify({at:today(),modules:moduleStats(),exams:state.exams.map(e=>({date:e.at,score:e.score,count:e.ids.length})),labs:state.labs},null,2))">导出学习分析</button></section>`}
